mapper.select:
select e.id, e.username, e.name, e.gender, e.phone, e.job, e.salary, e.image, e.entry_date, e.dept_id, e.create_time, e.update_time, d.name as deptName from emp e left join dept d on e.dept_id = d.id
e.name like concat('%', #{name}, '%')
and e.gender = #{gender}
and e.entry_date between #{begin} and #{end}
order by e.update_time desc

mapper.update:
update emp
username = #{username}, password = #{password}, name = #{name}, gender = #{gender}, phone = #{phone}, job = #{job}, salary = #{salary}, image = #{image}, entry_date = #{entryDate}, dept_id = #{deptId}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select id, username, name, gender, image
from emp
where username = #{username} and password = #{password}
